"use client";
import {useEffect,useRef,useState} from 'react';import {hotelClient,hotelRpc} from '@/lib/pilot';import {CashierJournalSelect} from './cashier-journal-select';import type {CashJournalSource,CashJournalCandidate} from '@/lib/cashier-journal-candidates';
type Props={source:CashJournalSource;disabled?:boolean;onSaved:()=>void};type Pending={id:string;journal:string};
export function CashierJournalLink(p:Props){return <LinkForm key={[p.source.scope.tenant,p.source.scope.property,p.source.scope.actor,p.source.kind,p.source.source,p.source.account].join(':')} {...p}/>}
function LinkForm({source,disabled=false,onSaved}:Props){const [candidate,setCandidate]=useState<CashJournalCandidate|null>(null),[confirmed,setConfirmed]=useState(false),[pending,setPending]=useState<Pending|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[saved,setSaved]=useState(false);const alive=useRef(false),lock=useRef(false);const {scope}=source,key=['irp-cash-journal-link',scope.tenant,scope.property,scope.actor,source.kind,source.source,source.account].join(':');
useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const p=JSON.parse(raw);if(![p.id,p.journal].every(v=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v)))throw Error('Saved journal link is invalid.');setPending(p)}}catch(e){setError(e instanceof Error?e.message:'Unable to recover journal link.')}return()=>{alive.current=false}},[key]);
async function submit(){if(lock.current||disabled||saved)return;lock.current=true;setBusy(true);setError('');try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen cash accounting.');let p=pending;if(!p){if(!candidate||!confirmed)throw Error('Select and confirm a journal.');if(sessionStorage.getItem(key)!==null)throw Error('An unresolved journal link exists. Reopen cash accounting.');p={id:crypto.randomUUID(),journal:candidate.journal_id};sessionStorage.setItem(key,JSON.stringify(p));setPending(p)}const result=await hotelRpc<Record<string,unknown>>(source.kind==='opening'?'link_cashier_opening_journal':'link_cashier_custody_journal',{p_tenant:scope.tenant,p_property:scope.property,...(source.kind==='opening'?{p_session:source.source}:{p_movement:source.source}),p_request:p.id,p_journal:p.journal,p_account:source.account,p_confirmed:true});const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen cash accounting.');if(result.schema_version!==1||result.tenant_id!==scope.tenant||result.property_id!==scope.property||result.actor_id!==scope.actor||result.request_id!==p.id||result.journal_id!==p.journal||result.account_id!==source.account||result[source.kind==='opening'?'session_id':'movement_id']!==source.source||result.new_journal_posted!==false)throw Error('Journal link receipt does not match. Retry the saved request.');sessionStorage.removeItem(key);if(alive.current){setPending(null);setSaved(true);onSaved()}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to link journal.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
return <section>{saved?<p role="status">Journal linked. Refresh cash sources to review the current accounting status.</p>:<><CashierJournalSelect source={source} disabled={disabled||busy||!!pending} onSelect={v=>{setCandidate(v);setConfirmed(false)}}/>{candidate&&!pending&&<label><input type="checkbox" checked={confirmed} disabled={disabled||busy} onChange={e=>setConfirmed(e.target.checked)}/>I confirm this journal records this cash source</label>}{pending&&<p>A saved journal link needs confirmation. Retrying uses the same request.</p>}<button type="button" disabled={disabled||busy||(!pending&&(!candidate||!confirmed))} onClick={()=>void submit()}>{pending?'Retry saved journal link':'Link selected journal'}</button></>}{error&&<p role="alert">{error}</p>}</section>}
